#!/usr/bin/env bash
# xinmo.work 全托管自安装脚本（自包含，无需外部下载）
# 在 VPS 的 VNC 里：bash bootstrap.sh
set -euo pipefail

echo "== 解包站点与 API =="
mkdir -p /tmp/xinmo-bundle
echo '' | base64 -d > /tmp/xinmo-bundle/bundle.tar.gz
tar -xzf /tmp/xinmo-bundle/bundle.tar.gz -C /tmp/xinmo-bundle

echo "== 安装静态站 =="
sudo mkdir -p /var/www
sudo rm -rf /var/www/xinmo-site
sudo cp -r /tmp/xinmo-bundle/site /var/www/xinmo-site
sudo chown -R www-data:www-data /var/www/xinmo-site 2>/dev/null || true

echo "== 安装动态 API =="
sudo useradd --system --home-dir /opt/xinmo-api --shell /usr/sbin/nologin xinmoapi 2>/dev/null || true
sudo mkdir -p /opt/xinmo-api
sudo cp /tmp/xinmo-bundle/api/server.py /opt/xinmo-api/server.py
sudo cp /tmp/xinmo-bundle/deploy/dynamic.env /opt/xinmo-api/dynamic.env
sudo chown -R xinmoapi:xinmoapi /opt/xinmo-api
sudo chmod 600 /opt/xinmo-api/dynamic.env
sudo cp /tmp/xinmo-bundle/deploy/dynamic-api.service /etc/systemd/system/dynamic-api.service
sudo systemctl daemon-reload
sudo systemctl enable --now dynamic-api

echo "== 配置 Caddy =="
if grep -q 'stage.xinmo.work' /etc/caddy/Caddyfile 2>/dev/null; then
  echo "Caddy 已配置 stage.xinmo.work，跳过"
else
  sudo cp /tmp/xinmo-bundle/deploy/Caddyfile-snippet /tmp/caddy-add
  sudo bash -c 'cat /tmp/caddy-add >> /etc/caddy/Caddyfile'
  sudo systemctl reload caddy
fi

sleep 3
echo "== 自检 =="
sudo systemctl is-active dynamic-api
curl -sS --max-time 10 http://127.0.0.1:8790/api/health || true
echo ""
echo "== DONE =="
echo "测试域名: https://stage.xinmo.work （需先加 DNS：stage A -> 47.79.16.152）"
echo "实时日志: sudo journalctl -u dynamic-api -f"
